@startuml

class Center {
  + Name : string
}

class Room {
  + Number : int
  + Capacity : int
}

class Person {
  + FirstName : string
  + FamilyName : string
  + BirthDate : date
}

class Trainer extends Person {
  + Diploma : string
}

class Member extends Person {}

class Session {
  + Date : date
  + StartingHour : time
}

class IndividualSession extends Session {}

class GroupSession extends Session {
  + Type : string
}

class Participation {
}

Center "1" *-- "1..*" Room
Room "1" -- "0..*" Session

GroupSession "1" -- "1" Trainer
Trainer "1" -- "0..*" GroupSession : supervises

Person "1" -- "*" Participation
Participation "*" -- "1" Session

Person "1" -- "0..*" Trainer : is
Person "1" -- "0..*" Member : is

@enduml

